set-variable.value:
@{
            var form = context.Request.Body?.AsFormUrlEncodedContent(true);
            return form != null && form.ContainsKey("client_id") ? (form["client_id"].FirstOrDefault() ?? "").Trim() : "";
        }

@{
            var form = context.Request.Body?.AsFormUrlEncodedContent(true);
            return form != null && form.ContainsKey("client_secret") ? (form["client_secret"].FirstOrDefault() ?? "").Trim() : "";
        }

@{
            var form = context.Request.Body?.AsFormUrlEncodedContent(true);
            return form != null && form.ContainsKey("scope") ? (form["scope"].FirstOrDefault() ?? "").Trim() : "";
        }

inbound.set-body:
@{
            var scope = context.Variables.GetValueOrDefault<string>("scope", "");
            if (scope.Length == 0) { scope = "${default_scope}"; }
            return "grant_type=client_credentials"
                + "&client_id=" + Uri.EscapeDataString(context.Variables.GetValueOrDefault<string>("clientId"))
                + "&client_secret=" + Uri.EscapeDataString(context.Variables.GetValueOrDefault<string>("clientSecret"))
                + "&scope=" + Uri.EscapeDataString(scope);
        }
